Item.method_code:
const { getState, favorites, rows, getProps, relatedTypeName } = options;
const { grid } = getState();
const selectedRows = grid.selectedRows;
if (selectedRows.length === 0) {
	return { hidden: true };
}

const configIds = selectedRows.reduce((result, id) => {
	const relatedId = rows.get(id, 'related_id');
	const relatedConfigId = rows.get(relatedId, 'config_id');
	const isNew = ArasModules.item.isNew(relatedTypeName, relatedId);
	if (relatedConfigId && !isNew) {
		result.add(relatedConfigId);
	}

return result;
}, new Set());
const props = getProps();
const favoritesStore = favorites.filterFavorites(
	props.favorites,
	'Item',
	({ additional_data: additionalData }) => configIds.has(additionalData.id)
);
const hidden = favoritesStore.length === 0;
const disabled = selectedRows.length > 1;
return { hidden, disabled };
